"""Evidence-bound TeX for the two separately frozen fixed-policy studies."""
import csv
import hashlib
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]


def read(p): return json.loads(p.read_text())
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def pct(x): return 'N/A' if x is None else f'{100*x:.1f}'
def prob(x): return 'N/A' if x is None else ('<0.001' if x<.001 else f'{x:.4g}')
def rows(p): return list(csv.DictReader(p.open()))
def esc(value): return str(value).replace('_',r'\_')

def load(study):
    b=ROOT/'results'/('policy_'+study+'_v1');p=read(b/'protocol.json');s=read(b/'analysis/scores.json');f=read(b/'predictions/frozen_manifest.json')
    assert s['protocol_sha256']==digest(b/'protocol.json')==f['protocol_sha256']
    assert s['frozen_manifest_sha256']==digest(b/'predictions/frozen_manifest.json')
    for name,h in f['files'].items(): assert digest(b/'predictions'/name)==h,name
    for name,h in p['code_sha256'].items(): assert digest(ROOT/name)==h,name
    return b,p,s


def make_policy_fragments():
    studies=[('Hydraulic',*load('hydraulic')),('Bearing',*load('paderborn'))]
    hs,bs=studies[0][3],studies[1][3]
    ht,bt=hs['totals'],bs['totals']
    class_audit=read(ROOT/'results/policy_error_classes_v1/audit.json')
    assert class_audit['post_hoc'] is True
    for rel,expected in class_audit['source_files_sha256'].items(): assert digest(ROOT/rel)==expected,rel
    assert class_audit['script_sha256']==digest(ROOT/'src/analysis/audit_policy_error_classes_v1.py')
    methods=r'''\subsection{Prospective new-data position and decision-check studies}
Two subsequent studies fix their new data, prompts, assignment schedule, code and scoring rules before new inference, after the earlier outcomes are known. The hydraulic source pool excludes all 54 previously used joint-condition blocks. Among 90 remaining eligible blocks, fixed hashes select six common valve--accumulator settings in the nine pump--cooler strata. Three disjoint panels each contain nine focal and nine background cycles, one of each role per stratum. This adds 27 focal and 27 background cycles from 54 new condition blocks on the same rig, not 54 devices. The original 28 physical-channel summaries and units are retained.

The separate Paderborn bearing task uses healthy and naturally damaged inner-/outer-race specimens produced in accelerated-life tests \citep{lessmeier2016benchmark}. A fixed specimen split assigns three bearings per class to the focal panel and two to its background. Each of nine focal bearings contributes one complete recording under each of four operating regimes (36 records); each of six other bearings contributes one recording under two fixed regimes (12 records). Hashed selection fixes the recording and regime choices without model outcomes. These are 15 physical specimens on one other test rig. No transient windows, fault thresholds or best-performing recordings are selected.

Seven bearing channels (force, two phase currents, speed, bearing-module temperature, torque and vibration) supply mean and population standard deviation. The three high-rate current/vibration channels additionally supply RMS, crest factor and Pearson kurtosis; vibration supplies five fixed relative-power bands over 0--100, 100--500, 500--2000, 2000--10000 and 10000--32000 Hz, giving 28 features in total. Computation uses the full recording and the documented nominal 64 kHz rate for those high-rate channels, retaining actual lengths and time-axis checks. The MAT unit fields are empty: physical amplitude units are unspecified in the files and values retain their recorded scale; dimensionless ratios are distinguished from physical units. Empty unit fields do not establish that the sensors were uncalibrated. No per-record bearing identity, operating-setting code, source filename or reference label enters the model payload.

Each new prompt contains one shared feature dictionary and six-decimal value arrays. This compact serialization is a new interface; it is not an exact-payload replication of earlier prompts. Condition F places the fixed focal group before its background; R places it after the same background, without changing any record or within-group order. Two sequential rounds each use three F/R pairs per panel. Within each round, hydraulic panel order is shuffled; within each pair, F/R are independently assigned to two near-simultaneous launch slots. A seed fixed before calls sets the entire schedule. The hydraulic design therefore plans 18 pairs/36 requests/648 output slots; the bearing design plans six pairs/12 requests/576 slots. Repeated outputs correspond to 27 and 36 distinct focal records, respectively, not to 324 and 432 independent sources.

Both studies use Sol following its earlier variability, a result-informed service choice that cannot support a model-family ranking. They request GPT-5.6 Sol at medium reasoning effort through fresh isolated subscription-authenticated CLI sessions, with tools, project context and demonstrations disabled. Requests start on a fixed 180-second grid with a 170-second timeout and at most two active calls. Each job has one invocation. A failed/invalid call, unknown usage, token-dispatch threshold or grid deadline stops later pairs; failed and unattempted slots remain visible. The hydraulic/bearing token thresholds are 900,000/1,000,000 observed input-plus-output tokens, including cached input. In-flight calls may exceed a dispatch threshold. Terminal outputs are audited and frozen before the answer key is opened for scoring.

For pair $j$, the position endpoint is $d_j=(C_{Fj}-C_{Rj})/n_j$, where $C$ counts usable correct focal labels and $n_j$ is the planned focal size. Failed requests supply zero usable correct output. The estimate is the mean over scheduled pairs. Only if every pair is dispatched, grid lateness is at most 3 s and launch skew at most 2 s is a two-sided within-pair sign-randomization reference calculated over all $2^J$ assignments. Its exactness additionally assumes the sharp null for slot outcomes, no cross-request interference or carryover, and assignment-invariant eligibility/complete-dispatch selection; timing checks alone do not prove these assumptions. This is a request-assignment analysis, not a test treating jointly generated labels as independent. The two datasets are analyzed separately; references are exploratory and unadjusted across datasets, with no threshold-based confirmation or pooled population claim. Sample size was fixed by feasibility rather than a population-effect power calculation.

\begin{figure}[htbp]\centering
\includegraphics[width=\linewidth]{figures/policy_design_v1.pdf}
\caption{Frozen paired-position and decision-check design within one panel--round. F/R columns denote input conditions, not launch order: each pair randomizes their two launch slots. F1 is the common initial diagnosis; F2 and R2 are contemporaneous alternative checks.}
\label{fig:policy_design}
\end{figure}

The engineering comparison fixes F1 as the initial label in each panel--round. \emph{Same} retains it only when F2 agrees; \emph{View} retains it only when R2 agrees. F2 and R2 are the two calls of the same second pair, making their time gaps from the common F1 similar. Both policies require two valid calls and otherwise abstain. Secondary policies use three F calls (or separately three R calls): majority returns a label with at least two votes and abstains on a three-way tie; unanimity requires all three labels to match. No policy is chosen or tuned after new results. ``First'' means frozen pair index, not earliest completion.

For every fixed policy we count accepted correct/error outputs, rejected initially correct/error outputs, required-call failures, coverage, error among accepted cases and usable correct yield (accepted correct divided by planned decisions). Voting corrections and harms are counted separately because voting may change the initial label. Same/View also report errors and correct labels rejected by only one gate. Policy denominators repeat the same sources across two rounds (54 hydraulic and 72 bearing decision opportunities). Costs are the actual requests, known tokens and summed client execution seconds of each policy's prescribed calls; shared experimental calls are charged to each hypothetical policy, not treated as free cached evidence. These are discrete policies, not a fitted continuous risk--coverage curve.
'''
    context=[r'\begin{table}[htbp]\centering\small',r'\caption{New randomized paired-position follow-ups. Correct F/R counts use planned focal slots; repeated outputs are not independent source units. The sign-randomization reference is conditional on the stated assumptions, not a population accuracy test.}',r'\label{tab:policy_context}',r'\begin{tabular}{@{}lrrrrrr@{}}\toprule',r'Task & Valid/planned & Pairs & F correct & R correct & $100\bar d$ & $p$ \\\midrule']
    for name,b,p,s in studies:
        c=s['context'];t=s['totals'];n=c['focal_slots_each_condition']
        context.append(f"{name} & {t['complete_sessions']}/{t['planned_sessions']} & {c['pairs_valid']}/{c['pairs_scheduled']} & {c['f_usable_correct']}/{n} & {c['r_usable_correct']}/{n} & {100*c['mean_f_minus_r_usable_correct_fraction']:.1f} & {prob(c['two_sided_sharp_null_p'])}"+r' \\')
    context += [r'\bottomrule\end{tabular}',r'\par\smallskip\footnotesize $100\bar d$ is the F-minus-R difference in percentage points. N/A denotes an ineligible randomization reference, not a nonsignificant result.',r'\end{table}']
    table=[r'\begin{table}[htbp]\centering\small',r'\caption{Fixed decision policies on new focal records. AC/AE: accepted correct/error; RC/RE: rejected initially correct/error. The denominator is 54 hydraulic or 72 bearing panel--round decisions. These gates retain or reject the same initial F1 label; secondary three-call policies are in the Supplement.}',r'\label{tab:fixed_policies}',r'\begin{tabular}{@{}llrrrrrr@{}}\toprule',r'Task & Policy & AC & AE & RC & RE & Coverage (\%) & Error$^a$ (\%) \\\midrule']
    labels={'Single_F':'Single F1','Same':'Same','View':'View'}
    for name,b,p,s in studies:
        for key,label in labels.items():
            m=s['policies'][key]
            table.append(f"{name} & {label} & {m['accepted_correct']} & {m['accepted_error']} & {m['rejected_base_correct']} & {m['rejected_base_error']} & {pct(m['coverage'])} & {pct(m['selective_error'])}"+r' \\')
        if name=='Hydraulic':table.append(r'\addlinespace')
    table += [r'\bottomrule\end{tabular}',r'\par\smallskip\footnotesize $^a$ Error among accepted decisions; N/A if none accepted. Required-call missingness and both F/R variants are reported in the Supplement. Rejected cases are not assumed repaired. AC divided by the planned denominator is usable correct yield.',r'\end{table}']
    costtable=[r'\begin{table}[htbp]\centering\small',r'\caption{Usable correct output and resources for the fixed initial-label policies. Tokens and client execution seconds sum the prescribed calls across panel--rounds; they are not per-record costs or deployed wall-clock latency.}',r'\label{tab:policy_resources}',r'\begin{tabular}{@{}llrrrr@{}}\toprule',r'Task & Policy & Correct/planned & Requests$^a$ & Tokens$^b$ & Seconds$^c$ \\\midrule']
    for name,b,p,s in studies:
        for key,label in labels.items():
            m=s['policies'][key]
            costtable.append(f"{name} & {label} & {m['accepted_correct']}/{m['planned']} & {m['attempted_requests']}/{m['planned_requests']} & {m['known_tokens']:,} & {m['client_service_seconds_sum']:.1f}"+r' \\')
    costtable += [r'\bottomrule\end{tabular}',r'\par\smallskip\footnotesize $^a$ Attempted/planned calls. $^b$ Known input-plus-output tokens; unknown usage is counted separately. $^c$ Sum of observed client subprocess durations; imposed grid waits are excluded.',r'\end{table}']
    result=[r'\subsection{New-data position contrasts and fixed-budget checks}',
      f"The new hydraulic schedule supplies {ht['complete_sessions']}/{ht['planned_sessions']} valid requests and {ht['valid_prediction_slots']}/{ht['planned_prediction_slots']} valid output slots; the bearing schedule supplies {bt['complete_sessions']}/{bt['planned_sessions']} and {bt['valid_prediction_slots']}/{bt['planned_prediction_slots']}, respectively. Each schedule retains its own failures, sources and time window. Table~\\ref{{tab:policy_context}} reports the assigned-request contrasts; Tables~\\ref{{tab:fixed_policies}} and~\\ref{{tab:policy_resources}} give the policy outcomes and resources.", '\n'.join(context),'\n'.join(table),'\n'.join(costtable)]
    for name,b,p,s in studies:
        fliprows=rows(b/'analysis/flips.csv')
        within=[int(r['flips']) for r in fliprows if r['kind'].startswith('within_') and r['flips']!='']
        cross=[int(r['flips']) for r in fliprows if r['kind']=='cross_FR' and r['flips']!='']
        denominator=9 if name=='Hydraulic' else 36
        if within and cross:
            result.append(f"Across {name.lower()} panel--rounds, identical-input pairs change {min(within)}--{max(within)}/{denominator} focal labels, and cross-position pairs change {min(cross)}--{max(cross)}/{denominator}. These dependent pair ranges describe repeatability and are not subtracted to estimate a corrected position effect.")
        m=s['policies'];inc=s['incremental_gate_rejections'];base=m['Single_F'];same=m['Same'];view=m['View'];maj=m['Majority_F']
        result.append(f"For {name.lower()} decisions, F1 makes {base['accepted_error']} errors and {base['accepted_correct']} correct predictions across {base['planned']} opportunities. Same rejects {same['rejected_base_error']} initially wrong and {same['rejected_base_correct']} initially correct decisions; View rejects {view['rejected_base_error']} and {view['rejected_base_correct']}, respectively. With both checks valid, View alone rejects {inc['view_only_reject_base_error']} errors and {inc['view_only_reject_base_correct']} correct labels that Same retains; Same alone rejects {inc['same_only_reject_base_error']} errors and {inc['same_only_reject_base_correct']} correct labels that View retains. Three-vote F corrects {maj['corrected_base_error']} initial errors, changes {maj['harmed_base_correct']} correct labels to errors and delivers {maj['accepted_correct']}/{maj['planned']} usable correct decisions.")
        rear=m['Single_R'];rear_vote=m['Majority_R'];rear_unanimity=m['Unanimity_R']
        result.append(f"The R variant is assessed in parallel: three-vote R corrects {rear_vote['corrected_base_error']} initial errors, changes {rear_vote['harmed_base_correct']} correct labels to errors and withholds {rear_vote['rejected_base_correct']} initially correct labels. Usable correct decisions change from {rear['accepted_correct']}/{rear['planned']} for R1 to {rear_vote['accepted_correct']}/{rear_vote['planned']} for its majority; accepted errors change from {rear['accepted_error']} to {rear_vote['accepted_error']}. Three-call R unanimity retains {rear_unanimity['accepted_error']} initial errors and rejects {rear_unanimity['rejected_base_correct']} initially correct labels. These outcomes preclude selecting a favorable position after inspecting its vote results.")
        result.append(f"The {name.lower()} study records {s['totals']['observed_total_tokens']:,} known tokens, with {s['totals']['unknown_usage_sessions']} attempted calls lacking usage. Same and View consume {same['known_tokens']:,} and {view['known_tokens']:,} known tokens for their prescribed call subsets. Equal request counts do not imply equal token cost or duration.")
    retained=class_audit['persistent_retained_errors']
    assert {(r['truth'],r['wrong_prediction']) for r in retained['records']}=={('Severe_leakage','Weak_leakage'),('Weak_leakage','No_leakage')}
    result.append(f"A post hoc class-level inspection identifies {retained['unique_cycles']} hydraulic focal cycles whose fault severity is underestimated: severe leakage is labeled weak leakage, and weak leakage is labeled no leakage. Both Same/View gates and both F/R unanimity gates retain these wrong labels in both rounds ({retained['repeated_decisions']} repeated decisions). This localized failure mode shows that the tested checks leave some severity underestimation unresolved; it neither estimates its population frequency nor identifies an internal model mechanism. The per-cycle source-bound audit is retained separately from the prospectively fixed policy scores.")
    abstract=(f"New frozen protocols yield {ht['complete_sessions']}/36 hydraulic and {bt['complete_sessions']}/12 bearing requests on previously unused hydraulic blocks and a second test rig. Across 54 repeated hydraulic decisions, replacing an identical-input check with a position-varied check retains {hs['policies']['View']['accepted_correct']-hs['policies']['Same']['accepted_correct']} more correct diagnoses but releases {hs['policies']['View']['accepted_error']-hs['policies']['Same']['accepted_error']} additional error. Across 72 bearing decisions, accepted errors fall from {bs['policies']['Same']['accepted_error']} to {bs['policies']['View']['accepted_error']} and accepted correct diagnoses rise from {bs['policies']['Same']['accepted_correct']} to {bs['policies']['View']['accepted_correct']}, yet {pct(bs['policies']['View']['selective_error'])}\\% of retained diagnoses are wrong. Voting benefits also differ across input positions.")
    discussion=[r'The practical comparison concerns where to spend one additional check, not whether repeated agreement certifies correctness. Same and View retain the same F1 label when accepted; neither can increase the number of correct F1 outputs. An increase in accepted-case accuracy must therefore be assessed alongside the correct labels withheld and the extra calls. Voting can correct or damage F1 and has a different action space.']
    for name,b,p,s in studies:
        m=s['policies'];v=m['View'];a=m['Same'];n=v['planned'];inc=s['incremental_gate_rejections']
        discussion.append(f"In {name.lower()}, replacing Same with View changes accepted errors from {a['accepted_error']} to {v['accepted_error']} and usable correct decisions from {a['accepted_correct']}/{n} to {v['accepted_correct']}/{n}. These paired counts define the observed tradeoff; they do not by themselves establish a lower field-maintenance loss. The incremental rejections in the results identify whether the position check contributes error signals absent from the repeated-input check, rather than crediting all rejection as useful.")
        if inc['view_only_reject_base_error']==0:
            discussion.append(f"In this {name.lower()} schedule, View detects no initial error that Same misses. Position variation therefore supplies no observed incremental error capture at the fixed check budget; any additional retained correct labels must be considered alongside the errors also released.")
    bearing_view=bs['policies']['View'];bearing_same=bs['policies']['Same']
    discussion.append(f"The bearing result illustrates why screening and diagnostic adequacy must be separated. View reduces accepted errors relative to Same, but {bearing_view['accepted_error']}/{bearing_view['accepted']} retained labels remain wrong and only {bearing_view['accepted_correct']}/{bearing_view['planned']} planned decisions yield a correct usable label. The same-input check also raises accepted-case error from {pct(bs['policies']['Single_F']['selective_error'])}\\% to {pct(bearing_same['selective_error'])}\\%. None of these outcomes establishes an adequate bearing diagnostic system. Poor base-task performance cannot be repaired by reporting a more favorable rejection count; base-task validity remains a prerequisite before a checking policy could justify use. The subsequent same-feature supervised benchmark tests one part of that prerequisite and does not establish adequate classification either.")
    discussion.append(r'These new records test rules fixed from prior reasoning and earlier evidence, but this remains exploratory and small. Operating regimes, specimens, prompt serialization, task and service time vary across the two systems. A policy difference here cannot be attributed exclusively to one internal model process, nor can success in one system validate the policy universally. A fixed-budget policy is defensible only with an explicit operating target and a prospective acceptance criterion for both its error outputs and its refusal burden.')
    conclusion=(f"New randomized request pairs and pre-fixed decision rules extend the audit to unused hydraulic condition blocks and a distinct bearing task. The observed Same-to-View change is {hs['policies']['Same']['accepted_error']} to {hs['policies']['View']['accepted_error']} accepted hydraulic errors and {bs['policies']['Same']['accepted_error']} to {bs['policies']['View']['accepted_error']} bearing errors, while retaining {hs['policies']['Same']['accepted_correct']} versus {hs['policies']['View']['accepted_correct']} and {bs['policies']['Same']['accepted_correct']} versus {bs['policies']['View']['accepted_correct']} correct decisions, respectively.")
    supplement=[r'\clearpage\section{New-data randomized position and fixed-policy studies}',r'\label{sec:policy_supp}',r'This appendix adds two prospectively frozen exploratory studies after the archived results. It does not complete the interrupted earlier hydraulic schedule. Exact new protocols, fixed input/answer separation, selection manifests, raw outputs and per-decision exports are in the local reconstruction package.',methods]
    for name,b,p,s in studies:
        supplement.append(r'\subsection{'+name+r' execution and decision accounting}')
        t=s['totals'];supplement.append(f"Scheduled/attempted/valid requests: {t['planned_sessions']}/{t['attempted_sessions']}/{t['complete_sessions']}; not attempted: {t['not_attempted_sessions']}; valid/planned full output slots: {t['valid_prediction_slots']}/{t['planned_prediction_slots']}; valid/planned focal slots: {t['focal_valid_slots']}/{t['focal_planned_slots']}; known tokens: {t['observed_total_tokens']:,}; unknown-usage attempts: {t['unknown_usage_sessions']}. The frozen protocol and output-manifest SHA-256 values are recorded in the package and the generated score artifact.")
        pp=rows(b/'analysis/randomized_pairs.csv')
        tt=[r'\begin{table}[htbp]\centering\small',r'\caption{'+name+r' paired request outcomes. F/R counts refer only to the fixed focal records. Client launch skew is not a server-time measurement.}',r'\label{tab:policy_pairs_'+p['dataset_id']+'}',r'\begin{tabular}{@{}lrrrrrr@{}}\toprule',r'Panel & Round & Repeat & F correct & R correct & Focal $n$ & Skew (s) \\\midrule']
        for r in pp:tt.append(f"{esc(r['panel'])} & {r['round']} & {r['repeat']} & {r['f_correct']} & {r['r_correct']} & {r['focal_n']} & {float(r['launch_skew_seconds']):.3f}"+r' \\' if r['launch_skew_seconds'] else f"{esc(r['panel'])} & {r['round']} & {r['repeat']} & {r['f_correct']} & {r['r_correct']} & {r['focal_n']} & N/A"+r' \\')
        tt += [r'\bottomrule\end{tabular}\end{table}'];supplement.append('\n'.join(tt))
        tt=[r'\begin{table}[htbp]\centering\small',r'\caption{'+name+r' complete fixed-policy outcomes, including R variants. Yield is accepted correct/planned. Missing means a required call was invalid or absent.}',r'\label{tab:policy_full_'+p['dataset_id']+'}',r'\begin{tabular}{@{}lrrrrrrr@{}}\toprule',r'Policy & AC & AE & RC & RE & Missing & Yield (\%) & Tokens \\\midrule']
        for k,m in s['policies'].items():tt.append(f"{esc(k)} & {m['accepted_correct']} & {m['accepted_error']} & {m['rejected_base_correct']} & {m['rejected_base_error']} & {m['required_call_missing']} & {pct(m['usable_correct_fraction'])} & {m['known_tokens']:,}"+r' \\')
        tt += [r'\bottomrule\end{tabular}\end{table}'];supplement.append('\n'.join(tt))
        ff=rows(b/'analysis/flips.csv');tt=[r'\begin{table}[htbp]\centering\small',r'\caption{'+name+r' all-pair focal flip ranges by panel--round. Within each condition there are three dependent pairs; across conditions there are nine. No flip-rate subtraction is used.}',r'\label{tab:policy_flips_'+p['dataset_id']+'}',r'\begin{tabular}{@{}llrrr@{}}\toprule',r'Panel & Round & Within F & Within R & Cross F/R \\\midrule']
        for block in sorted({r['block'] for r in ff},key=int):
            rr=[r for r in ff if r['block']==block];ranges=[]
            for kind in ['within_F','within_R','cross_FR']:
                vals=[int(r['flips']) for r in rr if r['kind']==kind and r['flips']!=''];ranges.append(f'{min(vals)}--{max(vals)}' if vals else 'N/A')
            tt.append(f"{esc(rr[0]['panel'])} & {rr[0]['round']} & "+' & '.join(ranges)+r' \\')
        tt += [r'\bottomrule\end{tabular}\end{table}'];supplement.append('\n'.join(tt))
        supplement.append(r'\FloatBarrier')
    supplement.append(r'The complete CSV exports additionally retain full-record labels, every gate action, the two one-sided incremental rejection sets, actual request start/end times, client execution durations and required-call costs. No source-pair resampling, continuous risk curve or independent-record significance test is added to these policies.')
    return {'POLICY_ABSTRACT':abstract,'POLICY_METHODS':methods,'POLICY_RESULTS':'\n\n'.join(result),'POLICY_DISCUSSION':'\n\n'.join(discussion),'POLICY_CONCLUSION':conclusion},'\n\n'.join(supplement)
